import re, pathlib
files=['/var/log/syslog','/var/log/auth.log']
email_re=re.compile(r"\b[a-zA-Z0-9._%+-]+@[a-zA-Z0-9.-]+\.[A-Za-z]{2,}\b")
phone_re=re.compile(r"(?:(?<!\d)(?:\+?\d{1,3}[\s.-]?)?(?:\(\d{2,4}\)[\s.-]?)?\d{3,4}[\s.-]?\d{3,4}[\s.-]?\d{3,4}(?!\d))")
for f in files:
    p=pathlib.Path(f)
    if not p.exists():
        print(f"{f}: MISSING")
        continue
    try:
        text=p.read_text(errors='ignore')
    except Exception as e:
        print(f"{f}: ERROR {e}")
        continue
    emails=set(email_re.findall(text))
    phones=set([m.strip() for m in phone_re.findall(text) if len(re.sub(r'\D','',m))>=10])
    print(f"{f}: emails={len(emails)} phones={len(phones)}")
    if emails:
        for e in sorted(emails)[:50]:
            print('  email:',e)
        if len(emails)>50: print('  ...')
    if phones:
        for ph in sorted(phones)[:50]:
            print('  phone:',ph)
        if len(phones)>50: print('  ...')
PY
